// ═══════ CLAUDE COMMANDS — MASTER CHEAT SHEET (bundled reference data) ═══════
// Static reference data for the Claude Commands library (UI: src/claude-commands.js).
// Compiled from official Anthropic docs (code.claude.com / platform.claude.com).
// Not vault data — safe to regenerate. 9 groups · 183 commands.
// Loaded as a standalone script in sidepanel.html before vault.js; exposes the global PV_CLAUDE_COMMANDS.
const PV_CLAUDE_COMMANDS = {"meta":{"title":"Claude Master Cheat Sheet","note":"Compiled from official Anthropic Claude Code docs (docs.claude.com now redirects to code.claude.com) and the Anthropic prompt-engineering docs; verified against the current official reference tables in Aug 2026.","compiledFrom":["https://code.claude.com/docs/en/commands","https://code.claude.com/docs/en/cli-reference","https://code.claude.com/docs/en/interactive-mode","https://code.claude.com/docs/en/permission-modes","https://code.claude.com/docs/en/hooks","https://code.claude.com/docs/en/mcp","https://code.claude.com/docs/en/sub-agents","https://code.claude.com/docs/en/skills","https://code.claude.com/docs/en/memory","https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices"]},"groups":[{"name":"Slash Commands","icon":"⌨️","source":"https://code.claude.com/docs/en/commands","commands":[{"name":"/help","description":"Shows Claude Code help and the list of available commands. Your first stop when you forget a command name or want to see what the CLI can do.","inject":"/help","tags":["claude-code","help","slash-command"],"example":""},{"name":"/clear","description":"Starts a fresh conversation with an empty context window. Memory files (CLAUDE.md) are kept and the previous conversation is still resumable; use it between unrelated tasks to stop old context from bleeding in.","inject":"/clear","tags":["claude-code","session","context","slash-command"],"example":"/clear"},{"name":"/compact","description":"Summarizes the conversation so far to free up context while preserving key information. Pass optional instructions to steer what the summary keeps.","inject":"/compact","tags":["claude-code","context","session","slash-command"],"example":"/compact focus on the auth refactor decisions"},{"name":"/context","description":"Visualizes current context-window usage as a colored grid, showing how much is spent on memory files, tools, system prompt, and conversation. Use it to see what loaded and diagnose why you are running low on context.","inject":"/context","tags":["claude-code","context","session","slash-command"],"example":""},{"name":"/model","description":"Switches the AI model for the session and saves it as your default (e.g. an Opus, Sonnet, or Haiku alias). Use it to trade speed for capability mid-task.","inject":"/model","tags":["claude-code","model","config","slash-command"],"example":"/model opus"},{"name":"/effort","description":"Sets the model effort (reasoning depth) level: low, medium, high, xhigh, max, ultracode, or auto. Higher effort thinks harder at higher cost.","inject":"/effort","tags":["claude-code","model","config","slash-command"],"example":"/effort high"},{"name":"/init","description":"Analyzes your codebase and generates a starting CLAUDE.md project guide with build commands, test instructions, and conventions it discovers. If a CLAUDE.md already exists it suggests improvements instead of overwriting.","inject":"/init","tags":["claude-code","memory","config","slash-command"],"example":"/init"},{"name":"/memory","description":"Opens and edits your CLAUDE.md / CLAUDE.local.md memory files across user and project scopes, and toggles auto-memory. Selecting a file opens it in your editor.","inject":"/memory","tags":["claude-code","memory","config","slash-command"],"example":""},{"name":"/config","description":"Opens the Settings interface, or sets preferences directly with key=value pairs. Controls theme, editor mode (including vim), session recap, and other options.","inject":"/config","tags":["claude-code","config","settings","slash-command"],"example":"/config"},{"name":"/permissions","description":"Opens the permissions manager to set allow, ask, and deny rules for commands and tools, and to review recently denied actions. This is how you pre-approve or block specific tools.","inject":"/permissions","tags":["claude-code","permissions","config","slash-command"],"example":""},{"name":"/plan","description":"Switches into plan mode for a single prompt so Claude researches and proposes changes without editing your source until you approve the plan. Good before large or risky changes.","inject":"/plan","tags":["claude-code","permissions","plan-mode","slash-command"],"example":"/plan add rate limiting to the API"},{"name":"/agents","description":"Manages subagent configurations. In current versions it points you to ask Claude or edit the .claude/agents/ files directly; earlier versions opened an interactive creation wizard.","inject":"/agents","tags":["claude-code","subagents","config","slash-command"],"example":""},{"name":"/skills","description":"Manages custom skills (reusable instruction packages stored as SKILL.md files that load on demand). Lists available skills and helps create or edit them.","inject":"/skills","tags":["claude-code","skills","config","slash-command"],"example":""},{"name":"/mcp","description":"Manages Model Context Protocol server connections: shows status and tool counts, authenticates OAuth servers in the browser, and enables, disables, or reconnects servers.","inject":"/mcp","tags":["claude-code","mcp","config","slash-command"],"example":"/mcp"},{"name":"/hooks","description":"Views the hook configurations wired to tool and lifecycle events, so you can confirm which shell commands fire on PreToolUse, PostToolUse, Stop, and other events.","inject":"/hooks","tags":["claude-code","hooks","config","slash-command"],"example":""},{"name":"/status","description":"Shows current session status: the active authentication method, model, version, working directory, and connection details. Useful for confirming you are logged in with the right account.","inject":"/status","tags":["claude-code","session","diagnostics","slash-command"],"example":""},{"name":"/doctor","description":"Runs a comprehensive setup checkup that diagnoses installation and configuration issues, flags unused tools, proposes CLAUDE.md trims, and offers fixes.","inject":"/doctor","tags":["claude-code","diagnostics","config","slash-command"],"example":""},{"name":"/debug","description":"Enables debug logging for the session and helps troubleshoot runtime issues, capturing detailed logs of what Claude Code is doing.","inject":"/debug","tags":["claude-code","diagnostics","slash-command"],"example":"/debug MCP server keeps disconnecting"},{"name":"/cost","description":"Shows token usage and cost for the current session. An alias for /usage.","inject":"/cost","tags":["claude-code","session","cost","slash-command"],"example":""},{"name":"/usage","description":"Shows token usage, costs, and plan usage limits for the session.","inject":"/usage","tags":["claude-code","session","cost","slash-command"],"example":""},{"name":"/login","description":"Signs in to your Anthropic account (claude.ai subscription or Console). Needed to make model requests and to load claude.ai connectors.","inject":"/login","tags":["claude-code","auth","session","slash-command"],"example":""},{"name":"/logout","description":"Signs out of your Anthropic account and clears the stored session credentials.","inject":"/logout","tags":["claude-code","auth","session","slash-command"],"example":""},{"name":"/add-dir","description":"Adds an extra working directory for the current session so Claude can read and edit files outside the launch directory without restarting.","inject":"/add-dir","tags":["claude-code","session","files","slash-command"],"example":"/add-dir ../shared-lib"},{"name":"/cd","description":"Moves the session to a new working directory, changing where Claude runs commands and resolves relative paths.","inject":"/cd","tags":["claude-code","session","files","slash-command"],"example":"/cd packages/web"},{"name":"/resume","description":"Returns to an earlier conversation, either through an interactive picker or by session name, restoring its full context.","inject":"/resume","tags":["claude-code","session","slash-command"],"example":"/resume"},{"name":"/rewind","description":"Rolls both code and conversation back to an earlier checkpoint (or by a number of lines), undoing Claude's edits and restoring a previous state.","inject":"/rewind","tags":["claude-code","session","checkpoint","slash-command"],"example":""},{"name":"/branch","description":"Creates a branch of the current conversation so you can try a different direction without losing the original thread.","inject":"/branch","tags":["claude-code","session","slash-command"],"example":"/branch try-postgres"},{"name":"/fork","description":"Copies the current conversation into a new background session, letting the original continue while a fork explores separately.","inject":"/fork","tags":["claude-code","session","background","slash-command"],"example":""},{"name":"/diff","description":"Opens an interactive diff viewer showing your uncommitted changes, so you can review everything Claude edited before committing.","inject":"/diff","tags":["claude-code","git","review","slash-command"],"example":""},{"name":"/review","description":"Runs a fast single-pass, read-only review of a GitHub pull request, summarizing issues without modifying code.","inject":"/review","tags":["claude-code","git","review","slash-command"],"example":"/review 456"},{"name":"/security-review","description":"Checks the current diff for security vulnerabilities such as injection, auth, and data-exposure risks before you ship.","inject":"/security-review","tags":["claude-code","review","security","slash-command"],"example":""},{"name":"/simplify","description":"Refactors the changed code for readability and maintainability without hunting for bugs; a quality-only cleanup pass.","inject":"/simplify","tags":["claude-code","review","refactor","slash-command"],"example":""},{"name":"/verify","description":"Verifies your code changes for quality before committing, checking that the work holds together.","inject":"/verify","tags":["claude-code","review","slash-command"],"example":""},{"name":"/install-github-app","description":"Installs the Claude GitHub App for a repository, enabling PR reviews and GitHub-triggered Claude workflows.","inject":"/install-github-app","tags":["claude-code","git","integration","slash-command"],"example":""},{"name":"/tasks","description":"Lists the session's background work, including running background shells and subagents, where you can also stop them. Distinct from Claude's own to-do checklist.","inject":"/tasks","tags":["claude-code","session","background","slash-command"],"example":""},{"name":"/background","description":"Detaches the current session to run as a background agent, freeing your terminal while Claude keeps working.","inject":"/background","tags":["claude-code","background","session","slash-command"],"example":""},{"name":"/subtask","description":"Hands a side task to a subagent that works in its own context and returns the result into your conversation, keeping the main thread clean.","inject":"/subtask","tags":["claude-code","subagents","session","slash-command"],"example":"/subtask find every call site of getUser()"},{"name":"/btw","description":"Asks a quick side question about your current work without adding it to conversation history. The answer appears in a dismissible overlay and answers only from context already loaded (no tool access).","inject":"/btw","tags":["claude-code","session","slash-command"],"example":"/btw what was that config file name again?"},{"name":"/goal","description":"Sets a goal condition so Claude keeps working autonomously until it is met; pass clear to remove it.","inject":"/goal","tags":["claude-code","session","slash-command"],"example":"/goal all tests pass"},{"name":"/export","description":"Exports the current conversation as plain text to a file for sharing or archiving.","inject":"/export","tags":["claude-code","session","slash-command"],"example":"/export session.txt"},{"name":"/copy","description":"Copies the last assistant response (or the Nth) to your clipboard as raw text.","inject":"/copy","tags":["claude-code","session","slash-command"],"example":"/copy"},{"name":"/feedback","description":"Sends product feedback about Claude Code to Anthropic from inside the session.","inject":"/feedback","tags":["claude-code","meta","slash-command"],"example":"/feedback plan mode should remember my last plan"},{"name":"/keybindings","description":"Opens the keyboard shortcuts (keybindings) file so you can customize or rebind keys.","inject":"/keybindings","tags":["claude-code","config","keyboard","slash-command"],"example":""},{"name":"/ide","description":"Manages IDE integrations (VS Code, JetBrains) and shows connection status.","inject":"/ide","tags":["claude-code","integration","config","slash-command"],"example":""},{"name":"/terminal-setup","description":"Installs the Shift+Enter multiline key binding for terminals that need it (VS Code, Cursor, Alacritty, Zed, and similar).","inject":"/terminal-setup","tags":["claude-code","config","keyboard","slash-command"],"example":""},{"name":"/vim","description":"Toggles vim-style editing in the prompt. In current versions this is set via /config -> Editor mode rather than a standalone command, but vim keybindings for prompt editing remain available.","inject":"/config","tags":["claude-code","config","keyboard","slash-command"],"example":""},{"name":"/upgrade","description":"Upgrades Claude Code to the latest version from within the session.","inject":"/upgrade","tags":["claude-code","meta","slash-command"],"example":""},{"name":"/exit","description":"Exits the Claude Code CLI, ending the interactive session.","inject":"/exit","tags":["claude-code","session","slash-command"],"example":""},{"name":"/web-search","description":"Searches the web for information directly from the session.","inject":"/web-search","tags":["claude-code","search","slash-command"],"example":"/web-search latest node LTS version"}]},{"name":"CLI & Startup","icon":"💻","source":"https://code.claude.com/docs/en/cli-reference","commands":[{"name":"claude","description":"Starts an interactive Claude Code session in the current directory.","inject":"claude","tags":["claude-code","cli","startup"],"example":"claude"},{"name":"claude \"query\"","description":"Starts an interactive session seeded with an initial prompt.","inject":"claude \"explain the auth flow\"","tags":["claude-code","cli","startup"],"example":"claude \"refactor utils.py for readability\""},{"name":"claude -p / --print","description":"Runs the query non-interactively (headless/SDK mode), prints the response, and exits. The core building block for scripts and pipelines.","inject":"claude -p \"<prompt>\"","tags":["claude-code","cli","headless","automation"],"example":"cat error.log | claude -p \"summarize the root cause\""},{"name":"claude -c / --continue","description":"Loads and continues the most recent conversation in the current directory.","inject":"claude -c","tags":["claude-code","cli","session"],"example":"claude -c -p \"now add tests\""},{"name":"claude -r / --resume","description":"Resumes a specific past session by ID or name, or shows an interactive picker.","inject":"claude -r \"<session>\"","tags":["claude-code","cli","session"],"example":"claude -r auth-refactor \"continue where we left off\""},{"name":"claude update","description":"Updates Claude Code to the latest version.","inject":"claude update","tags":["claude-code","cli","maintenance"],"example":""},{"name":"claude doctor","description":"Prints read-only installation and settings diagnostics to troubleshoot a broken setup.","inject":"claude doctor","tags":["claude-code","cli","diagnostics"],"example":""},{"name":"claude install","description":"Installs or reinstalls the native Claude Code binary; an optional version pins a specific release.","inject":"claude install","tags":["claude-code","cli","maintenance"],"example":"claude install latest"},{"name":"claude mcp","description":"Configures Model Context Protocol servers (add, list, get, remove, login, and more subcommands).","inject":"claude mcp","tags":["claude-code","cli","mcp"],"example":"claude mcp list"},{"name":"claude auth login","description":"Signs in to your Anthropic account from the command line.","inject":"claude auth login","tags":["claude-code","cli","auth"],"example":""},{"name":"claude auth status","description":"Shows the current authentication status as JSON.","inject":"claude auth status","tags":["claude-code","cli","auth"],"example":""},{"name":"claude setup-token","description":"Generates a long-lived OAuth token for use in CI and scripts.","inject":"claude setup-token","tags":["claude-code","cli","auth","automation"],"example":""},{"name":"--model","description":"Sets the model for the session using an alias (opus, sonnet, haiku) or a full model ID.","inject":"claude --model <alias-or-id>","tags":["claude-code","cli","model"],"example":"claude --model opus"},{"name":"--fallback-model","description":"Enables automatic fallback to the specified model(s) when the primary model is overloaded.","inject":"claude --fallback-model <alias-or-id>","tags":["claude-code","cli","model"],"example":""},{"name":"--permission-mode","description":"Starts in a specific permission mode: default (manual), acceptEdits, plan, auto, dontAsk, or bypassPermissions.","inject":"claude --permission-mode plan","tags":["claude-code","cli","permissions"],"example":"claude --permission-mode acceptEdits"},{"name":"--dangerously-skip-permissions","description":"Skips all permission prompts (equivalent to --permission-mode bypassPermissions). Only use in isolated containers or VMs; refused when running as root.","inject":"claude --dangerously-skip-permissions","tags":["claude-code","cli","permissions","danger"],"example":""},{"name":"--allowedTools","description":"Lists tools that may execute without prompting for permission (allow rules).","inject":"claude --allowedTools \"<tool>\" \"<tool>\"","tags":["claude-code","cli","permissions"],"example":"claude --allowedTools \"Read\" \"Bash(npm test)\""},{"name":"--disallowedTools","description":"Lists deny rules for tools that must never run.","inject":"claude --disallowedTools \"<tool>\"","tags":["claude-code","cli","permissions"],"example":"claude --disallowedTools \"Bash(rm*)\""},{"name":"--add-dir","description":"Adds additional working directories Claude may read and edit beyond the launch directory.","inject":"claude --add-dir <path>","tags":["claude-code","cli","files"],"example":"claude --add-dir ../shared-config"},{"name":"--output-format","description":"Sets the print-mode output format: text, json, or stream-json. Use json/stream-json to parse results in scripts.","inject":"claude -p \"<prompt>\" --output-format json","tags":["claude-code","cli","headless","automation"],"example":"claude -p \"list TODOs\" --output-format stream-json --verbose"},{"name":"--input-format","description":"Sets the print-mode input format: text or stream-json (for streaming multi-turn input).","inject":"claude -p --input-format stream-json","tags":["claude-code","cli","headless","automation"],"example":""},{"name":"--max-turns","description":"Limits the number of agentic turns Claude may take in a headless run.","inject":"claude -p \"<prompt>\" --max-turns <n>","tags":["claude-code","cli","headless","automation"],"example":"claude -p \"fix the lint errors\" --max-turns 10"},{"name":"--verbose","description":"Enables verbose logging with full turn-by-turn output.","inject":"claude --verbose","tags":["claude-code","cli","diagnostics"],"example":""},{"name":"--mcp-config","description":"Loads MCP servers from JSON files or inline JSON strings for this run.","inject":"claude --mcp-config <file-or-json>","tags":["claude-code","cli","mcp"],"example":"claude --mcp-config ./servers.json"},{"name":"--strict-mcp-config","description":"Uses only the MCP servers passed via --mcp-config, ignoring all other MCP configuration sources.","inject":"claude --strict-mcp-config --mcp-config <file>","tags":["claude-code","cli","mcp"],"example":""},{"name":"--append-system-prompt","description":"Appends custom text to the end of the default system prompt, for system-prompt-level instructions.","inject":"claude --append-system-prompt \"<text>\"","tags":["claude-code","cli","prompting"],"example":"claude --append-system-prompt \"Always write tests first.\""},{"name":"--system-prompt","description":"Replaces the entire default system prompt with custom text.","inject":"claude --system-prompt \"<text>\"","tags":["claude-code","cli","prompting"],"example":""},{"name":"--settings","description":"Loads settings from a JSON file path or an inline JSON string, layered on top of the normal settings hierarchy.","inject":"claude --settings <file-or-json>","tags":["claude-code","cli","config"],"example":"claude --settings ./ci-settings.json"},{"name":"--setting-sources","description":"Comma-separated list of which setting sources to load: user, project, local.","inject":"claude --setting-sources user,project","tags":["claude-code","cli","config"],"example":""},{"name":"--session-id","description":"Uses a specific session ID (a valid UUID) for the conversation, useful for deterministic automation.","inject":"claude --session-id <uuid>","tags":["claude-code","cli","session","automation"],"example":""},{"name":"--fork-session","description":"When resuming, creates a new session ID instead of reusing the original, preserving the source session.","inject":"claude -r <session> --fork-session","tags":["claude-code","cli","session"],"example":""},{"name":"--agents","description":"Defines custom subagents dynamically via JSON for this session.","inject":"claude --agents '<json>'","tags":["claude-code","cli","subagents"],"example":""},{"name":"--worktree / -w","description":"Creates or uses a git worktree for the session so changes stay isolated from your main checkout.","inject":"claude --worktree","tags":["claude-code","cli","git"],"example":"claude -w"},{"name":"--bg / --background","description":"Starts the session as a background agent and returns immediately.","inject":"claude --bg \"<prompt>\"","tags":["claude-code","cli","background"],"example":""},{"name":"--max-budget-usd","description":"Caps the dollar amount spent on API calls before the run stops.","inject":"claude --max-budget-usd <amount>","tags":["claude-code","cli","cost","automation"],"example":"claude -p \"big refactor\" --max-budget-usd 5"},{"name":"--version / -v","description":"Prints the installed Claude Code version number.","inject":"claude --version","tags":["claude-code","cli","diagnostics"],"example":""}]},{"name":"Keyboard Shortcuts","icon":"🎹","source":"https://code.claude.com/docs/en/interactive-mode","commands":[{"name":"Esc","description":"Interrupts Claude mid-turn so you can redirect, keeping the work done so far. When a dialog such as a permission prompt is open, Esc closes the dialog instead.","inject":"Esc","tags":["claude-code","keyboard","session"],"example":""},{"name":"Esc Esc (double)","description":"With text in the prompt, clears the input draft and saves it to history. With an empty prompt, opens the rewind menu to restore or summarize code and conversation from a previous point.","inject":"Esc Esc","tags":["claude-code","keyboard","checkpoint"],"example":""},{"name":"Shift+Tab","description":"Cycles the permission mode: default (Manual) -> acceptEdits -> plan, plus any enabled modes such as auto or bypassPermissions. The primary way to enter plan mode or accept-edits.","inject":"Shift+Tab","tags":["claude-code","keyboard","permissions","plan-mode"],"example":""},{"name":"Ctrl+C","description":"Interrupts a running operation. If nothing is running, the first press clears the prompt input and a second press exits Claude Code.","inject":"Ctrl+C","tags":["claude-code","keyboard","session"],"example":""},{"name":"Ctrl+D","description":"Exits the Claude Code session (press twice within 800ms to confirm). With text in the prompt, deletes the character after the cursor instead.","inject":"Ctrl+D","tags":["claude-code","keyboard","session"],"example":""},{"name":"Ctrl+L","description":"Redraws the screen, keeping input and conversation history. Use it to recover a garbled display; press twice quickly to run /clear.","inject":"Ctrl+L","tags":["claude-code","keyboard","display"],"example":""},{"name":"Ctrl+R","description":"Reverse-searches your command history: type to filter previous prompts and reuse them.","inject":"Ctrl+R","tags":["claude-code","keyboard","history"],"example":""},{"name":"Ctrl+O","description":"Toggles the transcript viewer, showing detailed tool usage, timestamps, and the model used on each message.","inject":"Ctrl+O","tags":["claude-code","keyboard","transcript"],"example":""},{"name":"Ctrl+B","description":"Moves a running Bash command or agent to the background so you can keep working. Tmux users press twice.","inject":"Ctrl+B","tags":["claude-code","keyboard","background"],"example":""},{"name":"Ctrl+T","description":"Toggles Claude's to-do checklist in the status area, showing pending, in-progress, and complete tasks.","inject":"Ctrl+T","tags":["claude-code","keyboard","tasks"],"example":""},{"name":"Ctrl+G","description":"Opens your prompt (or the proposed plan) in your default text editor for longer edits. Ctrl+X Ctrl+E is the readline-native equivalent.","inject":"Ctrl+G","tags":["claude-code","keyboard","editing"],"example":""},{"name":"Ctrl+Z","description":"Suspends Claude Code to your shell (Unix only); run fg to resume.","inject":"Ctrl+Z","tags":["claude-code","keyboard","session"],"example":""},{"name":"Ctrl+X Ctrl+K","description":"Stops all running background subagents in the session. Press twice within 3 seconds to confirm.","inject":"Ctrl+X Ctrl+K","tags":["claude-code","keyboard","subagents"],"example":""},{"name":"Up / Down arrows","description":"Moves the cursor within multi-row input; once on the first or last row, navigates command history. Ctrl+P / Ctrl+N behave the same.","inject":"Up / Down","tags":["claude-code","keyboard","history"],"example":""},{"name":"Option+P / Alt+P","description":"Switches the model without clearing your current prompt.","inject":"Alt+P","tags":["claude-code","keyboard","model"],"example":""},{"name":"Option+T / Alt+T","description":"Toggles extended thinking mode on or off.","inject":"Alt+T","tags":["claude-code","keyboard","thinking"],"example":""},{"name":"/ (at start)","description":"Opens the command menu: type / to see and filter all built-in commands, skills, and plugin/MCP commands.","inject":"/","tags":["claude-code","keyboard","slash-command"],"example":""},{"name":"! (at start)","description":"Enters shell mode: runs a command directly, adds its output to the session, and (by default) has Claude respond to it.","inject":"!","tags":["claude-code","keyboard","shell","bash"],"example":"! npm test"},{"name":"@ (file mention)","description":"Triggers file-path autocomplete so you can reference a specific file or directory in your prompt.","inject":"@","tags":["claude-code","keyboard","files"],"example":"review @src/auth.ts for bugs"},{"name":": (emoji shortcode)","description":"Type a :name: shortcode to insert an emoji, or two or more characters for a suggestion popup.","inject":":","tags":["claude-code","keyboard","input"],"example":":rocket:"},{"name":"? (on empty input)","description":"Toggles the keyboard shortcut help panel when the prompt is empty.","inject":"?","tags":["claude-code","keyboard","help"],"example":""},{"name":"\\ + Enter","description":"Inserts a newline for multiline input; works in every terminal.","inject":"\\ + Enter","tags":["claude-code","keyboard","multiline"],"example":""},{"name":"Shift+Enter","description":"Adds a newline in multiline input; native in iTerm2, WezTerm, Ghostty, Kitty, Warp, Apple Terminal, and Windows Terminal (run /terminal-setup elsewhere).","inject":"Shift+Enter","tags":["claude-code","keyboard","multiline"],"example":""},{"name":"Ctrl+J","description":"Inserts a newline for multiline input in any terminal without configuration.","inject":"Ctrl+J","tags":["claude-code","keyboard","multiline"],"example":""},{"name":"Ctrl+V","description":"Pastes an image from the clipboard, inserting an [Image #N] chip you can reference in your prompt (Alt+V on Windows/WSL).","inject":"Ctrl+V","tags":["claude-code","keyboard","input","image"],"example":""},{"name":"Ctrl+A / Ctrl+E","description":"Moves the cursor to the start (Ctrl+A) or end (Ctrl+E) of the current line.","inject":"Ctrl+A / Ctrl+E","tags":["claude-code","keyboard","editing"],"example":""},{"name":"Ctrl+W","description":"Deletes the previous word and stores it for pasting with Ctrl+Y.","inject":"Ctrl+W","tags":["claude-code","keyboard","editing"],"example":""},{"name":"Ctrl+U / Ctrl+K","description":"Deletes from the cursor to the start of the line (Ctrl+U) or to the end of the line (Ctrl+K); Ctrl+Y pastes it back.","inject":"Ctrl+U / Ctrl+K","tags":["claude-code","keyboard","editing"],"example":""}]},{"name":"Modes & Permissions","icon":"🛡️","source":"https://code.claude.com/docs/en/permission-modes","commands":[{"name":"default (Manual) mode","description":"Reviews every action: Claude reads freely but asks before editing files, running commands, or making network requests. Labeled Manual in the CLI. The safest baseline for sensitive work.","inject":"claude --permission-mode default","tags":["claude-code","permissions","mode"],"example":"claude --permission-mode manual"},{"name":"acceptEdits mode","description":"Auto-approves file creates/edits and common filesystem commands (mkdir, touch, mv, cp, etc.) inside your working directory, so you review changes after the fact via git diff. Press Shift+Tab once from Manual to enter.","inject":"claude --permission-mode acceptEdits","tags":["claude-code","permissions","mode"],"example":""},{"name":"plan mode","description":"Tells Claude to research and propose changes without editing your source; edits stay blocked until you approve the plan. Enter with Shift+Tab or prefix a prompt with /plan.","inject":"claude --permission-mode plan","tags":["claude-code","permissions","plan-mode"],"example":"/plan migrate the build to Vite"},{"name":"auto mode","description":"Runs everything without routine prompts while a separate classifier model reviews each action for safety, blocking escalations and destructive operations. Available on qualifying accounts and models; reduces prompt fatigue on long tasks.","inject":"claude --permission-mode auto","tags":["claude-code","permissions","mode","auto"],"example":""},{"name":"dontAsk mode","description":"Auto-denies anything that would otherwise prompt, running only pre-approved allow-rule tools and read-only commands; never waits for input. Built for locked-down CI and scripts.","inject":"claude --permission-mode dontAsk","tags":["claude-code","permissions","mode","ci"],"example":""},{"name":"bypassPermissions mode","description":"Disables all permission prompts and safety checks so tool calls run immediately. Only for isolated containers/VMs; refused under root/sudo. Equivalent to --dangerously-skip-permissions.","inject":"claude --permission-mode bypassPermissions","tags":["claude-code","permissions","mode","danger"],"example":"claude --dangerously-skip-permissions"},{"name":"Cycle modes (Shift+Tab)","description":"Press Shift+Tab during a session to cycle default -> acceptEdits -> plan (plus any enabled optional modes). The status bar shows the active mode, e.g. accept edits on or plan mode on.","inject":"Shift+Tab","tags":["claude-code","permissions","keyboard"],"example":""},{"name":"Set default mode","description":"Set a persistent default permission mode in a settings file via permissions.defaultMode. Repositories cannot grant themselves auto or bypass; those must live in user or managed settings.","inject":"{\n  \"permissions\": {\n    \"defaultMode\": \"acceptEdits\"\n  }\n}","tags":["claude-code","permissions","config"],"example":""},{"name":"Allow / ask / deny rules","description":"Layer permission rules on top of any mode to pre-approve, force a prompt on, or block specific tools. Deny and ask rules apply in every mode, including bypassPermissions.","inject":"{\n  \"permissions\": {\n    \"allow\": [\"Bash(npm test)\"],\n    \"deny\": [\"Bash(rm -rf *)\"]\n  }\n}","tags":["claude-code","permissions","config"],"example":""}]},{"name":"Hooks","icon":"🪝","source":"https://code.claude.com/docs/en/hooks","commands":[{"name":"PreToolUse","description":"Fires before a tool call executes; can block or modify the call. The place to enforce hard rules regardless of what Claude decides.","inject":"PreToolUse","tags":["claude-code","hooks","permissions"],"example":""},{"name":"PostToolUse","description":"Fires after a tool call succeeds; used for logging, validation, or transforming output (e.g. auto-formatting edited files).","inject":"PostToolUse","tags":["claude-code","hooks"],"example":""},{"name":"PostToolUseFailure","description":"Fires after a tool call fails; used for error handling or logging.","inject":"PostToolUseFailure","tags":["claude-code","hooks"],"example":""},{"name":"PostToolBatch","description":"Fires after a full batch of parallel tool calls resolves; for batch-level decisions.","inject":"PostToolBatch","tags":["claude-code","hooks"],"example":""},{"name":"UserPromptSubmit","description":"Fires when you submit a prompt, before Claude processes it; used for prompt validation, filtering, or injecting context.","inject":"UserPromptSubmit","tags":["claude-code","hooks","prompting"],"example":""},{"name":"PermissionRequest","description":"Fires when a tool call needs a permission decision; used for custom auto-approval or denial logic.","inject":"PermissionRequest","tags":["claude-code","hooks","permissions"],"example":""},{"name":"PermissionDenied","description":"Fires when the auto-mode classifier denies a tool call; can signal a retry with permission.","inject":"PermissionDenied","tags":["claude-code","hooks","permissions"],"example":""},{"name":"Notification","description":"Fires when Claude Code sends a notification; used for monitoring or custom alerting (desktop, Slack, etc.).","inject":"Notification","tags":["claude-code","hooks"],"example":""},{"name":"Stop","description":"Fires when Claude finishes responding; used for validation or to prevent the turn from stopping until conditions are met.","inject":"Stop","tags":["claude-code","hooks"],"example":""},{"name":"SubagentStart","description":"Fires when a subagent is spawned; used for logging or validation.","inject":"SubagentStart","tags":["claude-code","hooks","subagents"],"example":""},{"name":"SubagentStop","description":"Fires when a subagent finishes; used for cleanup or injecting context back into the parent.","inject":"SubagentStop","tags":["claude-code","hooks","subagents"],"example":""},{"name":"SessionStart","description":"Fires when a session begins or resumes; used to load development context and set up the environment.","inject":"SessionStart","tags":["claude-code","hooks","session"],"example":""},{"name":"SessionEnd","description":"Fires when a session terminates; used for cleanup and logging.","inject":"SessionEnd","tags":["claude-code","hooks","session"],"example":""},{"name":"PreCompact","description":"Fires before context compaction; can block compaction or preserve state.","inject":"PreCompact","tags":["claude-code","hooks","context"],"example":""},{"name":"PostCompact","description":"Fires after context compaction completes; used for logging or re-injecting context.","inject":"PostCompact","tags":["claude-code","hooks","context"],"example":""},{"name":"Setup","description":"Fires when Claude Code starts with --init-only or maintenance flags; for one-time CI/script preparation.","inject":"Setup","tags":["claude-code","hooks","ci"],"example":""},{"name":"InstructionsLoaded","description":"Fires when a CLAUDE.md or .claude/rules/*.md file loads; useful for logging exactly which instruction files loaded and why.","inject":"InstructionsLoaded","tags":["claude-code","hooks","memory"],"example":""},{"name":"SessionEnd / lifecycle events","description":"Other documented lifecycle hooks include UserPromptExpansion, MessageDisplay, TaskCreated, TaskCompleted, StopFailure, ConfigChange, CwdChanged, FileChanged, WorktreeCreate, WorktreeRemove, Elicitation, and ElicitationResult, each firing at the moment its name describes.","inject":"CwdChanged","tags":["claude-code","hooks","lifecycle"],"example":""}]},{"name":"MCP","icon":"🔌","source":"https://code.claude.com/docs/en/mcp","commands":[{"name":"claude mcp add (HTTP)","description":"Adds a remote HTTP MCP server (the recommended transport for cloud services). Add --header to pass a bearer token or API key.","inject":"claude mcp add --transport http <name> <url>","tags":["claude-code","mcp","http"],"example":"claude mcp add --transport http notion https://mcp.notion.com/mcp"},{"name":"claude mcp add (SSE)","description":"Adds a remote Server-Sent Events MCP server. SSE is deprecated in favor of HTTP but some services still expose only an SSE endpoint.","inject":"claude mcp add --transport sse <name> <url>","tags":["claude-code","mcp","sse"],"example":"claude mcp add --transport sse asana https://mcp.asana.com/sse"},{"name":"claude mcp add (stdio)","description":"Adds a local stdio MCP server that runs as a process on your machine. Use -- to separate Claude's flags from the server command and args.","inject":"claude mcp add [options] <name> -- <command> [args...]","tags":["claude-code","mcp","stdio"],"example":"claude mcp add --env AIRTABLE_API_KEY=KEY airtable -- npx -y airtable-mcp-server"},{"name":"claude mcp add-json","description":"Adds a server from a raw JSON config string; the way to add WebSocket (type ws) servers and paste configs copied from server docs.","inject":"claude mcp add-json <name> '<json>'","tags":["claude-code","mcp","config"],"example":"claude mcp add-json weather '{\"type\":\"http\",\"url\":\"https://api.weather.com/mcp\"}'"},{"name":"claude mcp list","description":"Lists all configured MCP servers with a health status next to each (Connected, Needs authentication, Failed to connect).","inject":"claude mcp list","tags":["claude-code","mcp"],"example":""},{"name":"claude mcp get","description":"Shows full details and connection status for a single configured server.","inject":"claude mcp get <name>","tags":["claude-code","mcp"],"example":"claude mcp get notion"},{"name":"claude mcp remove","description":"Removes a configured MCP server from your configuration.","inject":"claude mcp remove <name>","tags":["claude-code","mcp"],"example":"claude mcp remove notion"},{"name":"claude mcp login / logout","description":"Runs a configured server's OAuth flow from the shell (login) or clears its stored credentials (logout), without opening the /mcp panel.","inject":"claude mcp login <name>","tags":["claude-code","mcp","auth"],"example":"claude mcp login sentry"},{"name":"claude mcp add-from-claude-desktop","description":"Imports MCP servers you already configured in Claude Desktop (macOS and WSL only) via an interactive picker.","inject":"claude mcp add-from-claude-desktop","tags":["claude-code","mcp","import"],"example":""},{"name":"--scope (local / project / user)","description":"Chooses where a server is stored: local (default, private to you in this project), project (shared via a checked-in .mcp.json), or user (private, across all your projects).","inject":"claude mcp add --scope project --transport http <name> <url>","tags":["claude-code","mcp","scope"],"example":"claude mcp add --scope user --transport http hubspot https://mcp.hubspot.com/anthropic"},{"name":"/mcp","description":"In-session panel to view MCP servers and tool counts, authenticate OAuth servers in the browser, toggle servers on/off, and reconnect them.","inject":"/mcp","tags":["claude-code","mcp","slash-command"],"example":""},{"name":".mcp.json (project config)","description":"Project-scoped servers live in a .mcp.json file at the repo root; check it in so teammates get the same tools. Supports ${VAR} and ${VAR:-default} environment-variable expansion.","inject":"{\n  \"mcpServers\": {\n    \"shared-server\": {\n      \"type\": \"http\",\n      \"url\": \"https://example.com/mcp\"\n    }\n  }\n}","tags":["claude-code","mcp","config","scope"],"example":""}]},{"name":"Subagents & Skills","icon":"🤖","source":"https://code.claude.com/docs/en/sub-agents","commands":[{"name":"/agents","description":"Manages subagents. In current versions it prints a reminder to ask Claude or edit .claude/agents/ directly; earlier versions opened a Running/Library wizard for creating, editing, and deleting them.","inject":"/agents","tags":["claude-code","subagents","slash-command"],"example":""},{"name":".claude/agents/ (project subagents)","description":"Project-scoped subagent definitions, discovered by walking up from the working directory. Check them into version control so the team shares them. Closest-to-cwd definition wins on name conflicts.","inject":".claude/agents/<name>.md","tags":["claude-code","subagents","config","project"],"example":""},{"name":"~/.claude/agents/ (user subagents)","description":"Personal subagent definitions available across all your projects. Scanned recursively so you can organize them into subfolders; identity comes only from the name frontmatter field.","inject":"~/.claude/agents/<name>.md","tags":["claude-code","subagents","config","user"],"example":""},{"name":"Subagent file (frontmatter)","description":"A subagent is a Markdown file: YAML frontmatter for config plus a body that becomes the system prompt. Only name and description are required; other fields include tools, model, permissionMode, mcpServers, hooks, skills, and memory.","inject":"---\nname: code-reviewer\ndescription: Reviews code for quality and best practices\ntools: Read, Glob, Grep\nmodel: sonnet\n---\n\nYou are a senior code reviewer. When invoked, review the diff and report issues by severity.","tags":["claude-code","subagents","config"],"example":""},{"name":"Invoke a subagent","description":"Claude auto-delegates to a subagent when a task matches its description, or you can name it explicitly in your prompt. Subagents run in their own context and return only a summary.","inject":"Use the code-reviewer subagent to review my staged changes","tags":["claude-code","subagents","prompting"],"example":""},{"name":"SKILL.md (skills)","description":"A skill packages reusable instructions in a SKILL.md file with frontmatter; the body loads only when the skill is used, so long reference material costs nothing until needed. Invoke directly with /skill-name or let Claude load it when relevant.","inject":".claude/skills/<name>/SKILL.md","tags":["claude-code","skills","config"],"example":""},{"name":"Custom commands (.claude/commands/)","description":"Custom slash commands are now merged into skills: a file at .claude/commands/deploy.md and a skill at .claude/skills/deploy/SKILL.md both create /deploy. Existing commands/ files keep working.","inject":".claude/commands/<name>.md","tags":["claude-code","skills","config","slash-command"],"example":""},{"name":"/skills","description":"Lists and manages custom skills available in the session.","inject":"/skills","tags":["claude-code","skills","slash-command"],"example":""},{"name":"/code-review (bundled skill)","description":"A deeper bundled skill that reviews the diff for correctness bugs and cleanup; --fix applies findings, --comment posts them as PR comments, and an effort level tunes thoroughness.","inject":"/code-review","tags":["claude-code","skills","review"],"example":"/code-review high --fix"},{"name":"/plugin","description":"Manages Claude Code plugins, which bundle skills, subagents, commands, hooks, and MCP servers for one-step install and team consistency.","inject":"/plugin","tags":["claude-code","plugins","slash-command"],"example":"/plugin install mcp-server-dev@claude-plugins-official"},{"name":"/plugin marketplace add","description":"Registers a plugin marketplace (e.g. a GitHub repo) so you can browse and install its plugins.","inject":"/plugin marketplace add <owner/repo>","tags":["claude-code","plugins","marketplace","slash-command"],"example":"/plugin marketplace add anthropics/claude-plugins-official"}]},{"name":"Memory & Config","icon":"🧠","source":"https://code.claude.com/docs/en/memory","commands":[{"name":"CLAUDE.md (project memory)","description":"A markdown file of persistent project instructions (build/test commands, conventions, architecture) that loads at the start of every session. Store at ./CLAUDE.md or ./.claude/CLAUDE.md and check it into version control. Aim for under 200 lines.","inject":"./CLAUDE.md","tags":["claude-code","memory","config","project"],"example":""},{"name":"~/.claude/CLAUDE.md (user memory)","description":"Personal instructions that apply to all your projects, such as code-style preferences and tooling shortcuts.","inject":"~/.claude/CLAUDE.md","tags":["claude-code","memory","config","user"],"example":""},{"name":"CLAUDE.local.md (local memory)","description":"Private, project-specific preferences (sandbox URLs, test data) that load alongside CLAUDE.md. Add it to .gitignore so it is not committed.","inject":"./CLAUDE.local.md","tags":["claude-code","memory","config","local"],"example":""},{"name":"@path imports in CLAUDE.md","description":"Pull additional files into memory with @path/to/file syntax (relative or absolute, up to four hops deep). Wrap a path in backticks to mention it without importing.","inject":"See @README for overview and @docs/git-instructions.md for the workflow.","tags":["claude-code","memory","config"],"example":""},{"name":".claude/rules/ (path-scoped rules)","description":"Split large instructions into topic files under .claude/rules/. Add a paths: frontmatter list so a rule only loads into context when Claude works with matching files.","inject":"---\npaths:\n  - \"src/api/**/*.ts\"\n---\n\n# API rules\n- All endpoints must validate input.","tags":["claude-code","memory","config"],"example":""},{"name":"/memory","description":"Lists and opens your CLAUDE.md, CLAUDE.local.md, and other memory files across scopes, and toggles auto-memory. Selecting a file opens it in your editor.","inject":"/memory","tags":["claude-code","memory","slash-command"],"example":""},{"name":"/init","description":"Generates a starting CLAUDE.md by analyzing your codebase; suggests improvements instead of overwriting if one exists.","inject":"/init","tags":["claude-code","memory","config","slash-command"],"example":""},{"name":"Ask Claude to remember","description":"Auto-memory: telling Claude 'always use pnpm, not npm' or 'remember that tests need a local Redis' saves the fact to per-repo auto-memory under ~/.claude/projects/<project>/memory/, loaded at the start of future sessions. (The old '#' inline-memory shortcut has been discontinued.)","inject":"Remember: always run `make lint` before committing.","tags":["claude-code","memory","prompting"],"example":""},{"name":"/config","description":"Opens the Settings interface or sets preferences directly. Controls theme, editor mode, session recap, and more.","inject":"/config","tags":["claude-code","config","settings","slash-command"],"example":""},{"name":"settings.json hierarchy","description":"Claude Code layers settings by scope: managed/enterprise policy (highest, cannot be overridden), then project-local (.claude/settings.local.json), project-shared (.claude/settings.json), and user (~/.claude/settings.json). Higher scopes win, and some values (auto/bypass modes) are ignored from project files for safety.","inject":".claude/settings.json","tags":["claude-code","config","settings"],"example":""},{"name":"Managed policy CLAUDE.md","description":"Organization-wide instructions deployed by IT that apply to every session on a machine and cannot be excluded. Locations: macOS /Library/Application Support/ClaudeCode/CLAUDE.md, Linux/WSL /etc/claude-code/CLAUDE.md, Windows C:\\Program Files\\ClaudeCode\\CLAUDE.md.","inject":"/etc/claude-code/CLAUDE.md","tags":["claude-code","config","memory","enterprise"],"example":""}]},{"name":"Prompting Patterns","icon":"✍️","source":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview","commands":[{"name":"Be clear and direct","description":"Treat Claude like a brilliant new hire with no context: state the task, the audience, the format, and the constraints explicitly. Vague prompts get vague answers; spelling out what 'good' looks like is the single highest-leverage fix.","inject":"Task: <what to do>\nAudience: <who it is for>\nConstraints: <length, tone, must-dos, must-not-dos>\nOutput format: <exact format>","tags":["prompting","clarity"],"example":""},{"name":"Use examples (multishot)","description":"Show 2-5 examples of the input-output pattern you want. Concrete examples steer format and edge-case handling far more reliably than description alone; wrap them in tags so Claude sees them as examples.","inject":"<examples>\n<example>\n<input>...</input>\n<output>...</output>\n</example>\n<example>\n<input>...</input>\n<output>...</output>\n</example>\n</examples>\n\nNow do the same for: <your input>","tags":["prompting","examples","multishot"],"example":""},{"name":"Let Claude think (chain of thought)","description":"For analysis, math, or multi-step reasoning, ask Claude to think step by step before answering. Giving it room to reason improves accuracy; have it show the reasoning in tags so you can separate work from the final answer.","inject":"Think step by step inside <thinking></thinking> tags, then give your final answer inside <answer></answer> tags.","tags":["prompting","reasoning","chain-of-thought"],"example":""},{"name":"Use XML tags","description":"Wrap distinct parts of a prompt (instructions, context, data, examples) in named XML tags so Claude can tell them apart. Reduces the chance Claude confuses your instructions with the content it should act on.","inject":"<instructions>\n<what to do>\n</instructions>\n<document>\n<paste content here>\n</document>","tags":["prompting","structure","xml"],"example":""},{"name":"Give Claude a role (system prompt)","description":"Set a role or persona in the system prompt to shape tone, depth, and priorities (e.g. 'You are a senior security engineer'). Role prompting is the most effective way to tune the voice and expertise of the whole response.","inject":"You are a <role> with expertise in <domain>. Your job is to <goal>. Prioritize <what matters most>.","tags":["prompting","system-prompt","role"],"example":""},{"name":"Prefill Claude's response","description":"Start Claude's reply for it (via the assistant turn) to control format, skip preambles, or force a structure. Prefilling with '{' pushes straight into JSON; prefilling a tag or heading locks the shape of the output.","inject":"Assistant: {","tags":["prompting","output","prefill"],"example":""},{"name":"Chain complex prompts","description":"Break a big task into a sequence of smaller prompts, feeding each step's output into the next (e.g. research -> outline -> draft -> review). Chaining keeps each step focused and makes errors easier to catch than one giant prompt.","inject":"Step 1: <first subtask, output in tags>\nStep 2: use the Step 1 output to <second subtask>\nStep 3: review the Step 2 output for <criteria>","tags":["prompting","workflow","chaining"],"example":""},{"name":"Structure long-context prompts","description":"With long documents, put the lengthy data near the top of the prompt and your question at the end, wrap each document in tags with metadata, and ask Claude to quote the relevant passages before answering.","inject":"<documents>\n<document index=\"1\">\n<source>...</source>\n<content>...</content>\n</document>\n</documents>\n\nFirst pull the quotes relevant to my question, then answer using only those quotes.","tags":["prompting","long-context","structure"],"example":""},{"name":"Tell Claude what to do, not what to avoid","description":"Positive instructions outperform negative ones: say 'respond in flowing prose' rather than 'do not use markdown'. Describing the desired behavior directly is more reliable than listing prohibitions.","inject":"Respond in <desired positive behavior>.","tags":["prompting","clarity","output"],"example":""}]}]};
